insert into public.questions (exam_category, subject, topic, type, difficulty, body, body_hi, question_data, options, marks_correct, marks_wrong, explanation, explanation_hi, concept_group_id, source_type, source_citation, status)
values
('upsc','Environment & Ecology','Fauna & Animal Behaviour','statement_based','medium','Consider the following statements about the hoolock gibbon:','हूलॉक गिबन के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Hoolock gibbons are the only apes found in India.", "They are found in the forests of north-eastern India, including the Hollongapar Gibbon Sanctuary in Assam.", "They live mainly on the forest floor and rarely climb trees."], "statements_hi": ["हूलॉक गिबन भारत में पाए जाने वाले एकमात्र कपि (ape) हैं।", "ये पूर्वोत्तर भारत के वनों में, असम के हॉलोंगापार गिबन अभयारण्य सहित, पाए जाते हैं।", "ये मुख्य रूप से वन की ज़मीन पर रहते हैं और पेड़ों पर कम ही चढ़ते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. Gibbons are apes (they have no tail), and the hoolock gibbons of the north-east are the only apes in India; the western hoolock is listed as Endangered and is in Schedule I. The Hollongapar Gibbon Sanctuary near Jorhat is named after them. Statement 3 is the reverse: gibbons are the most arboreal of the apes, moving through the canopy by swinging arm over arm (brachiation) and seldom coming to the ground. That is why fragmentation of the canopy -- a road or a rail line through the forest -- isolates their groups.','कथन 1 और 2 सही हैं। गिबन कपि हैं (इनकी पूँछ नहीं होती), और पूर्वोत्तर के हूलॉक गिबन भारत के एकमात्र कपि हैं; पश्चिमी हूलॉक संकटग्रस्त (Endangered) श्रेणी में है और अनुसूची I में है। जोरहाट के पास हॉलोंगापार गिबन अभयारण्य इन्हीं के नाम पर है। कथन 3 उलटा है: गिबन सबसे अधिक वृक्षवासी कपि हैं, जो बाँहों के सहारे झूलते हुए (brachiation) वितान में चलते हैं और कम ही ज़मीन पर आते हैं। इसीलिए वितान का टूटना, जैसे वन के बीच से सड़क या रेल लाइन, उनके समूहों को अलग-थलग कर देता है।','env-hoolock-gibbon','original_pattern_matched','IUCN Red List of Threatened Species: Hoolock hoolock; Wildlife (Protection) Act, 1972 (as amended in 2022), Schedules; Assam Forest Department -- Hollongapar Gibbon Sanctuary.','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','statement_based','medium','Consider the following statements about the crocodilians of India:','भारत के मगरमच्छ-वर्गीय जीवों (crocodilians) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The gharial has a long, narrow snout and feeds mainly on fish.", "The saltwater crocodile is found in India in Bhitarkanika in Odisha, the Sundarbans and the Andaman and Nicobar Islands.", "The National Chambal Sanctuary, spread across Rajasthan, Madhya Pradesh and Uttar Pradesh, holds the largest wild population of the gharial."], "statements_hi": ["घड़ियाल का थूथन लंबा और पतला होता है, और यह मुख्य रूप से मछलियाँ खाता है।", "भारत में खारे पानी का मगरमच्छ ओडिशा के भितरकनिका, सुंदरबन और अंडमान तथा निकोबार द्वीपसमूह में पाया जाता है।", "राजस्थान, मध्य प्रदेश और उत्तर प्रदेश में फैले राष्ट्रीय चंबल अभयारण्य में घड़ियाल की सबसे बड़ी जंगली आबादी है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. The gharial''s slender snout, lined with small interlocking teeth, is an adaptation for catching fish; it is Critically Endangered, and the Chambal, one of India''s least polluted large rivers, holds most of the surviving wild population. The saltwater (estuarine) crocodile, the largest living reptile, lives in India''s mangrove coasts -- Bhitarkanika, the Sundarbans and the Andaman and Nicobar Islands. The third species, the mugger, is a freshwater crocodile of rivers, lakes and marshes.','तीनों कथन सही हैं। छोटे, आपस में फँसने वाले दाँतों से भरा घड़ियाल का पतला थूथन मछली पकड़ने का अनुकूलन है; यह गंभीर रूप से संकटग्रस्त (Critically Endangered) है, और चंबल, जो भारत की सबसे कम प्रदूषित बड़ी नदियों में है, बची हुई जंगली आबादी के अधिकांश भाग का घर है। खारे पानी (ज्वारनदमुखी) का मगरमच्छ, जो सबसे बड़ा जीवित सरीसृप है, भारत के मैंग्रोव तटों पर रहता है: भितरकनिका, सुंदरबन और अंडमान तथा निकोबार द्वीपसमूह। तीसरी प्रजाति, मगर (mugger), नदियों, झीलों और दलदलों का मीठे पानी का मगरमच्छ है।','env-indian-crocodilians','original_pattern_matched','IUCN Red List of Threatened Species: Gavialis gangeticus, Crocodylus porosus, Crocodylus palustris; Madhya Pradesh Forest Department -- National Chambal Sanctuary.','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','statement_based','medium','Consider the following statements about the dugong:','डुगोंग के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["It is a marine herbivore that feeds mainly on seagrass.", "India''s first Dugong Conservation Reserve was notified in Palk Bay, Tamil Nadu.", "It is listed in Schedule I of the Wildlife (Protection) Act, 1972.", "Its closest living relatives are the dolphins and whales."], "statements_hi": ["यह एक समुद्री शाकाहारी जीव है जो मुख्य रूप से समुद्री घास खाता है।", "भारत का पहला डुगोंग संरक्षण आरक्षित क्षेत्र तमिलनाडु की पाक खाड़ी में अधिसूचित किया गया।", "यह वन्यजीव (संरक्षण) अधिनियम, 1972 की अनुसूची I में सूचीबद्ध है।", "डॉल्फ़िन और व्हेल इसके सबसे निकट के जीवित संबंधी हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": true}, {"id": "d", "body": "All four", "body_hi": "सभी चार", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1, 2 and 3 are correct. The dugong, or ''sea cow'', grazes seagrass meadows, which is why its survival in India is tied to the seagrass of the Gulf of Mannar, Palk Bay, the Gulf of Kutch and the Andamans; Tamil Nadu notified the Dugong Conservation Reserve in northern Palk Bay in 2022. It is in Schedule I and is listed as Vulnerable by the IUCN. Statement 4 is wrong: dugongs and manatees form the order Sirenia, whose closest living relatives are the elephants and hyraxes, not the whales and dolphins, which evolved from a different group of land mammals.','कथन 1, 2 और 3 सही हैं। डुगोंग, या ''समुद्री गाय'', समुद्री घास के मैदानों में चरता है, इसलिए भारत में इसका अस्तित्व मन्नार की खाड़ी, पाक खाड़ी, कच्छ की खाड़ी और अंडमान की समुद्री घास से जुड़ा है; तमिलनाडु ने 2022 में उत्तरी पाक खाड़ी में डुगोंग संरक्षण आरक्षित क्षेत्र अधिसूचित किया। यह अनुसूची I में है और IUCN इसे सुभेद्य (Vulnerable) मानता है। कथन 4 गलत है: डुगोंग और मैनेटी साइरेनिया (Sirenia) गण बनाते हैं, जिनके सबसे निकट के जीवित संबंधी हाथी और हाइरैक्स हैं; व्हेल और डॉल्फ़िन स्थलीय स्तनधारियों के एक अलग समूह से विकसित हुए।','env-dugong','original_pattern_matched','IUCN Red List of Threatened Species: Dugong dugon; Government of Tamil Nadu, notification of the Dugong Conservation Reserve, Palk Bay (2022); Wildlife (Protection) Act, 1972 (as amended in 2022), Schedules.','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','statement_based','medium','Consider the following statements about the Indian pangolin:','भारतीय पैंगोलिन (सल्लू साँप) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Its body is covered with overlapping scales made of keratin.", "All eight species of pangolin were moved to Appendix I of CITES in 2016.", "It feeds mainly on fruits and seeds."], "statements_hi": ["इसका शरीर केराटिन से बने, एक-दूसरे पर चढ़े शल्कों (scales) से ढका होता है।", "2016 में पैंगोलिन की सभी आठ प्रजातियों को CITES के परिशिष्ट I में रखा गया।", "यह मुख्य रूप से फल और बीज खाता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. Pangolins are the only mammals covered in scales, made of keratin like our nails; they roll into a ball when threatened. Demand for their scales and meat makes them among the most trafficked mammals, and CITES CoP17 (Johannesburg, 2016) moved all eight species to Appendix I, banning commercial trade. In India both the Indian and the Chinese pangolin are in Schedule I. Statement 3 is wrong: pangolins eat ants and termites, which they lick up with a long, sticky tongue after breaking open nests with their claws.','कथन 1 और 2 सही हैं। पैंगोलिन शल्कों से ढके एकमात्र स्तनधारी हैं; ये शल्क हमारे नाखूनों की तरह केराटिन के बने होते हैं, और खतरे में ये गेंद की तरह लिपट जाते हैं। शल्कों और मांस की माँग के कारण ये सबसे अधिक तस्करी होने वाले स्तनधारियों में हैं, और CITES CoP17 (जोहान्सबर्ग, 2016) ने सभी आठ प्रजातियों को परिशिष्ट I में रखकर इनके व्यावसायिक व्यापार पर रोक लगा दी। भारत में भारतीय और चीनी, दोनों पैंगोलिन अनुसूची I में हैं। कथन 3 गलत है: पैंगोलिन चींटियाँ और दीमक खाते हैं; ये पंजों से घोंसले तोड़कर लंबी, चिपचिपी जीभ से उन्हें चाट लेते हैं।','env-indian-pangolin','original_pattern_matched','CITES CoP17 (2016), Appendix I listing of Manis spp.; Wildlife (Protection) Act, 1972 (as amended in 2022), Schedules; IUCN Red List of Threatened Species: Manis crassicaudata.','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','statement_based','medium','Consider the following statements about the Amur falcon:','अमूर बाज़ (Amur falcon) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["It migrates from its breeding grounds in south-eastern Siberia and northern China to southern Africa, passing through north-eastern India.", "Large flocks roost around the Doyang reservoir in Nagaland during the autumn passage.", "On its way to Africa it crosses the Arabian Sea in a non-stop flight."], "statements_hi": ["यह दक्षिण-पूर्वी साइबेरिया और उत्तरी चीन के अपने प्रजनन-क्षेत्रों से पूर्वोत्तर भारत होते हुए दक्षिणी अफ़्रीका तक प्रवास करता है।", "शरद ऋतु के प्रवास के दौरान इसके बड़े झुंड नागालैंड के दोयांग जलाशय के आसपास बसेरा करते हैं।", "अफ़्रीका जाते समय यह बिना रुके उड़ान भरकर अरब सागर पार करता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. The Amur falcon, a small raptor, makes one of the longest migrations of any bird of prey. In October-November huge flocks gather around the Doyang reservoir in Wokha district, Nagaland, before moving on; the local community, which once trapped them, now protects them, and Pangti village calls itself the falcon capital. Satellite tagging has shown the falcons crossing the Arabian Sea and the western Indian Ocean non-stop to reach East and southern Africa. A student who assumes one statement must be false will pick ''Only two''.','तीनों कथन सही हैं। अमूर बाज़, एक छोटा शिकारी पक्षी, किसी भी शिकारी पक्षी के सबसे लंबे प्रवासों में से एक करता है। अक्टूबर-नवंबर में नागालैंड के वोखा ज़िले के दोयांग जलाशय के आसपास इसके विशाल झुंड इकट्ठा होते हैं और फिर आगे बढ़ते हैं; जो स्थानीय समुदाय कभी इन्हें पकड़ता था, अब इनकी रक्षा करता है, और पंगती गाँव स्वयं को बाज़ों की राजधानी कहता है। उपग्रह टैगिंग से पता चला है कि ये बाज़ बिना रुके अरब सागर और पश्चिमी हिंद महासागर पार करके पूर्वी और दक्षिणी अफ़्रीका पहुँचते हैं। जो विद्यार्थी मानता है कि एक कथन गलत होगा ही, वह ''केवल दो'' चुन लेगा।','env-amur-falcon','original_pattern_matched','Convention on Migratory Species -- Central Asian Flyway; Nagaland and Manipur Forest Departments with the Wildlife Institute of India -- satellite tagging of Amur falcons.','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','statement_based','medium','Consider the following statements about the great hornbill:','बड़े धनेश (great hornbill) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["During nesting, the female seals herself inside a tree cavity with mud and droppings, and the male feeds her through a narrow slit.", "Hornbills are important dispersers of the seeds of forest trees.", "In India, hornbills are found both in the Western Ghats and in north-eastern India.", "It is listed as Vulnerable on the IUCN Red List."], "statements_hi": ["घोंसला बनाते समय मादा मिट्टी और बीट से पेड़ के खोखले में स्वयं को बंद कर लेती है, और नर एक पतली दरार से उसे भोजन देता है।", "धनेश वन के पेड़ों के बीजों के महत्त्वपूर्ण प्रसारक हैं।", "भारत में धनेश पश्चिमी घाट और पूर्वोत्तर भारत, दोनों में पाए जाते हैं।", "IUCN रेड लिस्ट में इसे सुभेद्य (Vulnerable) श्रेणी में रखा गया है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": false}, {"id": "d", "body": "All four", "body_hi": "सभी चार", "isCorrect": true}]'::jsonb,2,0.66,'All four statements are correct. Hornbills nest in natural cavities of large old trees; the female walls herself in, moults, and depends on the male for food until the chicks are half-grown -- which is why felling of big trees hits them hard. Eating figs and other fruits and dropping the seeds far away, they are called ''farmers of the forest''. India''s nine hornbill species live in the Western Ghats, the north-east and the Himalayan foothills, and the great hornbill is listed as Vulnerable. A student who expects one statement to be false will pick ''Only three''.','चारों कथन सही हैं। धनेश बड़े, पुराने पेड़ों के प्राकृतिक खोखलों में घोंसला बनाते हैं; मादा स्वयं को भीतर बंद कर लेती है, उसके पंख झड़ जाते हैं, और चूज़ों के आधे बड़े होने तक वह भोजन के लिए नर पर निर्भर रहती है; इसीलिए बड़े पेड़ों की कटाई इन्हें बहुत नुकसान पहुँचाती है। अंजीर और दूसरे फल खाकर दूर-दूर बीज गिराने के कारण इन्हें ''वन के किसान'' कहा जाता है। भारत की नौ धनेश प्रजातियाँ पश्चिमी घाट, पूर्वोत्तर और हिमालय की तलहटी में रहती हैं, और बड़ा धनेश सुभेद्य (Vulnerable) श्रेणी में है। जो विद्यार्थी मानता है कि एक कथन गलत होगा ही, वह ''केवल तीन'' चुन लेगा।','env-great-hornbill','original_pattern_matched','IUCN Red List of Threatened Species: Buceros bicornis; Nature Conservation Foundation -- Hornbill Nest Adoption Programme, Arunachal Pradesh.','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','statement_based','medium','Consider the following statements about the purple frog (Nasikabatrachus sahyadrensis):','बैंगनी मेंढक (Nasikabatrachus sahyadrensis) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["It spends most of the year underground.", "It is endemic to the Western Ghats.", "It breeds in the dry winter months, when the streams run low."], "statements_hi": ["यह वर्ष का अधिकांश समय ज़मीन के भीतर बिताता है।", "यह पश्चिमी घाट का स्थानिक (endemic) जीव है।", "यह शुष्क सर्दी के महीनों में प्रजनन करता है, जब धाराओं में पानी कम होता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. Described only in 2003, the purple frog is a burrowing frog of the Western Ghats that lives several metres underground and feeds on termites; its closest relatives live in the Seychelles, a relic of the time when India and the Seychelles were joined. Statement 3 is wrong: it surfaces for only a day or two during the monsoon to mate beside fast-flowing streams, where its tadpoles cling to rocks. It is listed as Endangered.','कथन 1 और 2 सही हैं। 2003 में ही वर्णित बैंगनी मेंढक पश्चिमी घाट का बिल में रहने वाला मेंढक है, जो कई मीटर गहराई में रहता है और दीमक खाता है; इसके सबसे निकट संबंधी सेशेल्स में रहते हैं, जो उस समय की निशानी है जब भारत और सेशेल्स जुड़े हुए थे। कथन 3 गलत है: यह मानसून के दौरान केवल एक-दो दिन के लिए तेज़ बहती धाराओं के किनारे संभोग करने बाहर आता है, जहाँ इसके टैडपोल चट्टानों से चिपके रहते हैं। यह संकटग्रस्त (Endangered) श्रेणी में है।','env-purple-frog','original_pattern_matched','IUCN Red List of Threatened Species: Nasikabatrachus sahyadrensis; S.D. Biju and F. Bossuyt, Nature 425 (2003).','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','statement_based','medium','Consider the following statements about the Indian wild ass:','भारतीय जंगली गधे (घुड़खर) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["It is found mainly in the Little Rann of Kutch in Gujarat.", "It is a subspecies of the African wild ass.", "Its population has fallen steadily since the Wild Ass Sanctuary was created in the Little Rann."], "statements_hi": ["यह मुख्य रूप से गुजरात के छोटे रण (Little Rann of Kutch) में पाया जाता है।", "यह अफ़्रीकी जंगली गधे की एक उप-प्रजाति है।", "छोटे रण में जंगली गधा अभयारण्य बनने के बाद से इसकी आबादी लगातार घटी है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: the khur survives in the Little Rann of Kutch and its fringes, protected in the Wild Ass Sanctuary. Statement 2 is wrong: it is Equus hemionus khur, a subspecies of the Asiatic wild ass (onager); the African wild ass, ancestor of the domestic donkey, is a different species. Statement 3 reverses the trend: from a few hundred animals in the 1960s-70s the population has risen to several thousand, spreading into the Great Rann and nearby districts -- a conservation success, now pressed by salt-pan expansion and encroachment.','केवल कथन 1 सही है: घुड़खर छोटे रण और उसके किनारों पर जीवित है और जंगली गधा अभयारण्य में संरक्षित है। कथन 2 गलत है: यह Equus hemionus khur है, जो एशियाई जंगली गधे (ओनेजर) की उप-प्रजाति है; अफ़्रीकी जंगली गधा, जो पालतू गधे का पूर्वज है, एक अलग प्रजाति है। कथन 3 रुझान को उलट देता है: 1960-70 के दशक के कुछ सौ जानवरों से आबादी बढ़कर कई हज़ार हो गई है और बड़े रण तथा आसपास के ज़िलों तक फैल गई है; यह संरक्षण की सफलता है, जिस पर अब नमक के खेतों के विस्तार और अतिक्रमण का दबाव है।','env-indian-wild-ass','original_pattern_matched','Gujarat Forest Department -- Wild Ass Sanctuary, Little Rann of Kutch, and wild ass population estimation; IUCN Red List of Threatened Species: Equus hemionus.','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','statement_based','medium','Consider the following statements about the leatherback turtle:','लेदरबैक कछुए के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["It is the largest living turtle.", "In India it nests on the beaches of the Andaman and Nicobar Islands, including Great Nicobar.", "It feeds mainly on jellyfish."], "statements_hi": ["यह सबसे बड़ा जीवित कछुआ है।", "भारत में यह अंडमान और निकोबार द्वीपसमूह के तटों पर, ग्रेट निकोबार सहित, घोंसले बनाता है।", "यह मुख्य रूप से जेलीफ़िश खाता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. The leatherback, which can exceed two metres, lacks the hard shell of other turtles: its carapace is a leathery skin over small bones. Its Indian nesting beaches are in the Andaman and Nicobar Islands -- Galathea Bay on Great Nicobar and parts of Little Andaman -- which is why the effect of development on Great Nicobar is watched closely. It dives deep to feed on jellyfish, and mistakes floating plastic bags for them.','तीनों कथन सही हैं। दो मीटर से भी बड़ा हो सकने वाला लेदरबैक दूसरे कछुओं जैसा कठोर खोल नहीं रखता: इसका पृष्ठ-कवच छोटी हड्डियों के ऊपर चमड़े जैसी त्वचा है। भारत में इसके घोंसला-तट अंडमान और निकोबार द्वीपसमूह में हैं, जैसे ग्रेट निकोबार की गैलाथिया खाड़ी और लिटिल अंडमान के कुछ भाग; इसीलिए ग्रेट निकोबार में विकास के प्रभाव पर बारीकी से नज़र रखी जाती है। यह जेलीफ़िश खाने के लिए गहरे गोते लगाता है, और तैरती प्लास्टिक थैलियों को जेलीफ़िश समझ लेता है।','env-leatherback-turtle','original_pattern_matched','IUCN Red List of Threatened Species: Dermochelys coriacea; Zoological Survey of India -- marine turtles of the Andaman and Nicobar Islands.','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','statement_based','medium','Consider the following statements about protective resemblance in animals:','जीवों में सुरक्षात्मक समानता (protective resemblance) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["In Batesian mimicry, a harmless species imitates the warning signals of a harmful or unpalatable species.", "In Mullerian mimicry, a harmless species imitates a harmful species, as in Batesian mimicry.", "Camouflage and mimicry are the same thing: both work by making an animal hard to see."], "statements_hi": ["बेट्सियन अनुकरण (Batesian mimicry) में एक हानिरहित प्रजाति किसी हानिकारक या अरुचिकर प्रजाति के चेतावनी संकेतों की नकल करती है।", "म्यूलरियन अनुकरण (Mullerian mimicry) में, बेट्सियन अनुकरण की तरह, एक हानिरहित प्रजाति किसी हानिकारक प्रजाति की नकल करती है।", "छलावरण (camouflage) और अनुकरण (mimicry) एक ही बात है: दोनों जीव को मुश्किल से दिखने लायक बनाकर काम करते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: a harmless hoverfly that looks like a wasp, or a palatable butterfly that resembles a distasteful one, gains protection from predators that have learnt to avoid the model. Statement 2 is wrong: in Mullerian mimicry two or more genuinely harmful or unpalatable species share a similar warning pattern, so predators learn to avoid all of them faster. Statement 3 is wrong: camouflage makes an animal blend into its background, whereas mimicry makes it resemble another organism -- often conspicuously, as warning colours are meant to be seen.','केवल कथन 1 सही है: ततैया जैसी दिखने वाली हानिरहित होवरफ़्लाई, या अरुचिकर तितली से मिलती-जुलती स्वादिष्ट तितली, उन शिकारियों से सुरक्षा पाती है जिन्होंने मॉडल से बचना सीख लिया है। कथन 2 गलत है: म्यूलरियन अनुकरण में दो या अधिक वास्तव में हानिकारक या अरुचिकर प्रजातियाँ मिलता-जुलता चेतावनी पैटर्न साझा करती हैं, जिससे शिकारी उन सबसे जल्दी बचना सीख जाते हैं। कथन 3 गलत है: छलावरण जीव को उसकी पृष्ठभूमि में मिला देता है, जबकि अनुकरण उसे किसी दूसरे जीव जैसा बनाता है, जो प्रायः आसानी से दिखता है, क्योंकि चेतावनी रंग दिखाई देने के लिए ही होते हैं।','env-batesian-mullerian-mimicry','original_pattern_matched','NCERT Class XII, Biology -- Organisms and Populations (predation and defences of prey); NCERT Class XII, Biology -- Evolution.','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','statement_based','medium','Consider the following statements about sea turtles:','समुद्री कछुओं के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["In sea turtles, warmer nest temperatures produce mostly male hatchlings.", "The green turtle gets its name from the green colour of its shell.", "The hawksbill feeds mainly on seagrass."], "statements_hi": ["समुद्री कछुओं में घोंसले का अधिक तापमान अधिकतर नर बच्चे पैदा करता है।", "हरे कछुए (green turtle) का नाम उसके खोल के हरे रंग के कारण पड़ा है।", "हॉक्सबिल कछुआ मुख्य रूप से समुद्री घास खाता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": true}]'::jsonb,2,0.66,'None of the statements is correct. Sea turtles have temperature-dependent sex determination, and warmer sand produces mostly females -- which is why warming beaches threaten to skew their sex ratios. The green turtle is named after the greenish colour of its body fat, which comes from its herbivorous diet of seagrass and algae; its shell is olive-brown. The hawksbill, named for its narrow, pointed beak, feeds mainly on sponges on coral reefs; it is the green turtle that grazes seagrass.','कोई भी कथन सही नहीं है। समुद्री कछुओं में लिंग-निर्धारण तापमान पर निर्भर है, और गर्म रेत से अधिकतर मादाएँ पैदा होती हैं; इसीलिए गर्म होते तट उनके लिंग-अनुपात को बिगाड़ने का खतरा पैदा करते हैं। हरे कछुए का नाम उसकी शरीर-वसा के हरे रंग से पड़ा है, जो समुद्री घास और शैवाल वाले उसके शाकाहारी भोजन से आता है; उसका खोल जैतूनी-भूरा होता है। अपनी पतली, नुकीली चोंच के कारण नामित हॉक्सबिल मुख्य रूप से प्रवाल भित्तियों पर स्पंज खाता है; समुद्री घास हरा कछुआ चरता है।','env-sea-turtle-biology','original_pattern_matched','IUCN Red List of Threatened Species: Chelonia mydas, Eretmochelys imbricata; NOAA Fisheries -- sea turtle biology.','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','statement_based','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The Indian giant squirrel is the State animal of Maharashtra.", "The Bhimashankar Wildlife Sanctuary in Maharashtra was set up to protect the Indian giant squirrel."], "statements_hi": ["भारतीय विशाल गिलहरी महाराष्ट्र का राज्य पशु है।", "महाराष्ट्र का भीमाशंकर वन्यजीव अभयारण्य भारतीय विशाल गिलहरी की रक्षा के लिए बनाया गया था।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct. The Indian giant squirrel (Ratufa indica), locally called ''shekru'', is Maharashtra''s State animal, and the Bhimashankar Wildlife Sanctuary in the Sahyadri was declared in 1985 largely to protect it. A tree-dwelling squirrel up to a metre long including its tail, it is found in the deciduous and evergreen forests of peninsular India.','दोनों कथन सही हैं। भारतीय विशाल गिलहरी (Ratufa indica), जिसे स्थानीय रूप से ''शेकरू'' कहते हैं, महाराष्ट्र का राज्य पशु है, और सह्याद्रि का भीमाशंकर वन्यजीव अभयारण्य 1985 में मुख्य रूप से इसी की रक्षा के लिए घोषित हुआ। पूँछ सहित लगभग एक मीटर लंबी यह वृक्षवासी गिलहरी प्रायद्वीपीय भारत के पर्णपाती और सदाबहार वनों में मिलती है।','env-indian-giant-squirrel','original_pattern_matched','Maharashtra Forest Department -- Bhimashankar Wildlife Sanctuary and State symbols; Zoological Survey of India -- Ratufa indica.','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','statement_based','easy','Consider the following statements about the Asian elephant:','एशियाई हाथी के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["It is listed as Endangered on the IUCN Red List.", "All male Asian elephants have tusks.", "An elephant herd is usually led by an old female, the matriarch."], "statements_hi": ["IUCN रेड लिस्ट में इसे संकटग्रस्त (Endangered) श्रेणी में रखा गया है।", "सभी नर एशियाई हाथियों के दाँत (tusks) होते हैं।", "हाथियों के झुंड का नेतृत्व आम तौर पर एक बूढ़ी मादा करती है, जिसे मातृप्रधान (matriarch) कहते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 3 are correct. The Asian elephant is Endangered; its herds are family groups of related females and young, led by the oldest female, whose memory of water and food sources guides them. Statement 2 is wrong: unlike African elephants, many Asian bulls are tuskless (''makhnas''), and females have at most small tushes. Selective poaching of tuskers has raised the share of tuskless males in some populations.','कथन 1 और 3 सही हैं। एशियाई हाथी संकटग्रस्त है; इसके झुंड संबंधित मादाओं और बच्चों के पारिवारिक समूह होते हैं, जिनका नेतृत्व सबसे बूढ़ी मादा करती है, और पानी तथा भोजन के स्रोतों की उसकी स्मृति झुंड का मार्गदर्शन करती है। कथन 2 गलत है: अफ़्रीकी हाथियों के विपरीत, कई एशियाई नर बिना दाँत के होते हैं (''मखना''), और मादाओं के अधिक से अधिक छोटे दाँत (tushes) होते हैं। दाँत वाले नरों के चुनिंदा शिकार ने कुछ आबादियों में बिना दाँत वाले नरों का अनुपात बढ़ा दिया है।','env-asian-elephant-biology','original_pattern_matched','IUCN Red List of Threatened Species: Elephas maximus; Ministry of Environment, Forest and Climate Change -- Project Elephant.','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','statement_based','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The slender loris is a nocturnal primate found in southern India and Sri Lanka.", "Owls can turn their heads through a full 360 degrees."], "statements_hi": ["पतला लोरिस (slender loris) दक्षिण भारत और श्रीलंका में पाया जाने वाला एक निशाचर प्राइमेट है।", "उल्लू अपना सिर पूरे 360 डिग्री घुमा सकते हैं।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. The slender loris, a small, big-eyed primate, forages at night in the forests of the Western and Eastern Ghats and Sri Lanka. Statement 2 is a popular exaggeration: owls can rotate their heads through about 270 degrees, thanks to extra neck vertebrae and adaptations of the blood vessels in the neck -- they need to, because their eyes are fixed in their sockets.','केवल कथन 1 सही है। बड़ी आँखों वाला छोटा प्राइमेट पतला लोरिस पश्चिमी और पूर्वी घाट तथा श्रीलंका के वनों में रात में भोजन खोजता है। कथन 2 एक लोकप्रिय अतिशयोक्ति है: उल्लू गर्दन की अतिरिक्त कशेरुकाओं और गर्दन की रक्त-वाहिनियों के अनुकूलनों के कारण अपना सिर लगभग 270 डिग्री तक घुमा सकते हैं; उन्हें ऐसा करना पड़ता है, क्योंकि उनकी आँखें अपने गड्ढों में स्थिर होती हैं।','env-slender-loris-owls','original_pattern_matched','IUCN Red List of Threatened Species: Loris lydekkerianus; Zoological Survey of India -- primates of India.','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','statement_based','easy','Consider the following statements about the Indian peafowl:','भारतीय मोर के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["It is India''s national bird.", "It is listed in Schedule I of the Wildlife (Protection) Act, 1972.", "Only the male has the long, colourful train."], "statements_hi": ["यह भारत का राष्ट्रीय पक्षी है।", "यह वन्यजीव (संरक्षण) अधिनियम, 1972 की अनुसूची I में सूचीबद्ध है।", "केवल नर की लंबी, रंग-बिरंगी पूँछ (train) होती है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. The Indian peafowl was declared the national bird in 1963 and has the highest protection, under Schedule I. The long train of eye-spotted feathers belongs to the male (peacock) and is displayed to attract the female (peahen), a classic case of sexual selection.','तीनों कथन सही हैं। भारतीय मोर को 1963 में राष्ट्रीय पक्षी घोषित किया गया और इसे अनुसूची I के तहत सर्वोच्च संरक्षण प्राप्त है। आँख जैसे धब्बों वाले पंखों की लंबी पूँछ नर (मोर) की होती है, जिसे वह मादा (मोरनी) को आकर्षित करने के लिए फैलाता है; यह लैंगिक चयन का मानक उदाहरण है।','env-indian-peafowl','original_pattern_matched','Wildlife (Protection) Act, 1972 (as amended in 2022), Schedules; Ministry of Environment, Forest and Climate Change -- national symbols.','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','statement_based','easy','Consider the following statements about the greater one-horned rhinoceros:','एक सींग वाले बड़े गैंडे के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["In India it is found mainly in Assam and West Bengal.", "Its horn is made of bone.", "It is listed as Critically Endangered on the IUCN Red List."], "statements_hi": ["भारत में यह मुख्य रूप से असम और पश्चिम बंगाल में पाया जाता है।", "इसका सींग हड्डी का बना होता है।", "IUCN रेड लिस्ट में इसे गंभीर रूप से संकटग्रस्त (Critically Endangered) श्रेणी में रखा गया है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: its strongholds are Kaziranga, Orang and Pobitora in Assam and Jaldapara and Gorumara in West Bengal (with a reintroduced population at Dudhwa in Uttar Pradesh), besides Nepal. Statement 2 is wrong: the horn is made of keratin, the protein of hair and nails, which is why the medicinal claims that drive poaching are baseless. Statement 3 is wrong: after decades of protection its numbers recovered, and the IUCN lists it as Vulnerable.','केवल कथन 1 सही है: इसके मुख्य गढ़ असम के काज़ीरंगा, ओरांग और पोबितोरा तथा पश्चिम बंगाल के जलदापारा और गोरुमारा हैं (उत्तर प्रदेश के दुधवा में पुनर्स्थापित आबादी भी है), साथ ही नेपाल में भी। कथन 2 गलत है: सींग केराटिन का बना होता है, जो बाल और नाखूनों का प्रोटीन है; इसीलिए शिकार को बढ़ावा देने वाले औषधीय दावे निराधार हैं। कथन 3 गलत है: दशकों के संरक्षण के बाद इसकी संख्या बढ़ी, और IUCN इसे सुभेद्य (Vulnerable) मानता है।','env-one-horned-rhino','original_pattern_matched','IUCN Red List of Threatened Species: Rhinoceros unicornis; Assam Forest Department -- Kaziranga National Park.','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','statement_based','hard','Consider the following statements about bird migration through India:','भारत से होकर पक्षियों के प्रवास के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["India lies on the Central Asian Flyway, one of the world''s major bird migration routes.", "The demoiselle cranes that winter at Khichan in Rajasthan breed in the Arctic tundra.", "Keoladeo National Park remains the regular wintering ground of the western population of the Siberian crane.", "Greater flamingos breed in large numbers in the Great Rann of Kutch."], "statements_hi": ["भारत मध्य एशियाई उड़ान-मार्ग (Central Asian Flyway) पर स्थित है, जो विश्व के प्रमुख पक्षी-प्रवास मार्गों में से एक है।", "राजस्थान के खीचन में सर्दी बिताने वाले कुरजाँ (demoiselle cranes) आर्कटिक टुंड्रा में प्रजनन करते हैं।", "केवलादेव राष्ट्रीय उद्यान आज भी साइबेरियाई सारस की पश्चिमी आबादी का नियमित शीतकालीन स्थल है।", "बड़े राजहंस (greater flamingos) बड़े कच्छ के रण में बड़ी संख्या में प्रजनन करते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": false}, {"id": "d", "body": "All four", "body_hi": "सभी चार", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 4 are correct. The Central Asian Flyway links breeding grounds in Siberia and Central Asia with wintering grounds across the Indian subcontinent; and in good monsoon years greater flamingos breed in huge colonies (''Flamingo City'') in the Great Rann of Kutch. Statement 2 is wrong: the demoiselle cranes fed by the villagers of Khichan breed in the steppes of Central Asia, Mongolia and China, not the Arctic. Statement 3 is wrong: the western population of the Siberian crane, which wintered at Keoladeo (Bharatpur), dwindled to a last pair, and none has been seen there since the winter of 2001-02; the species now winters almost entirely in China''s Poyang Lake.','कथन 1 और 4 सही हैं। मध्य एशियाई उड़ान-मार्ग साइबेरिया और मध्य एशिया के प्रजनन-क्षेत्रों को पूरे भारतीय उपमहाद्वीप के शीतकालीन क्षेत्रों से जोड़ता है; और अच्छे मानसून वाले वर्षों में बड़े राजहंस बड़े कच्छ के रण में विशाल बस्तियों (''फ़्लेमिंगो सिटी'') में प्रजनन करते हैं। कथन 2 गलत है: खीचन के ग्रामीणों द्वारा दाना खिलाए जाने वाले कुरजाँ आर्कटिक में नहीं, मध्य एशिया, मंगोलिया और चीन के घास के मैदानों (स्टेपी) में प्रजनन करते हैं। कथन 3 गलत है: केवलादेव (भरतपुर) में सर्दी बिताने वाली साइबेरियाई सारस की पश्चिमी आबादी घटते-घटते अंतिम जोड़े तक रह गई, और 2001-02 की सर्दी के बाद वहाँ एक भी नहीं दिखा; यह प्रजाति अब लगभग पूरी तरह चीन की पोयांग झील में सर्दी बिताती है।','env-central-asian-flyway-birds','original_pattern_matched','Convention on Migratory Species -- Central Asian Flyway action plan; Bombay Natural History Society -- migratory birds of India.','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','statement_based','hard','Consider the following statements about how animals are adapted to climate:','जीवों के जलवायु के प्रति अनुकूलन के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Bergmann''s rule states that among related warm-blooded animals, those in colder climates tend to have smaller bodies.", "The kangaroo rat of North American deserts can meet its water needs from the internal oxidation of fat, without drinking water.", "Allen''s rule states that animals of colder climates tend to have longer ears and limbs."], "statements_hi": ["बर्गमान का नियम कहता है कि संबंधित नियततापी जीवों में ठंडी जलवायु वालों का शरीर छोटा होता है।", "उत्तरी अमेरिका के मरुस्थलों का कंगारू चूहा पानी पिए बिना, वसा के आंतरिक ऑक्सीकरण से अपनी पानी की ज़रूरत पूरी कर सकता है।", "एलन का नियम कहता है कि ठंडी जलवायु के जीवों के कान और अंग लंबे होते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 2 is correct: NCERT''s example of a desert mammal that gets its water from metabolism and concentrates its urine to save it. Statements 1 and 3 reverse the two rules. By Bergmann''s rule, related warm-blooded animals are larger in colder climates, since a larger body has less surface per unit volume and so loses heat more slowly. By Allen''s rule, cold-climate animals have shorter extremities -- ears, limbs, muzzles -- for the same reason, as in the short-eared Arctic fox compared with the long-eared fennec of the desert.','केवल कथन 2 सही है: यह NCERT का उस मरुस्थलीय स्तनधारी का उदाहरण है जो चयापचय से पानी पाता है और पानी बचाने के लिए अपने मूत्र को गाढ़ा करता है। कथन 1 और 3 दोनों नियमों को उलट देते हैं। बर्गमान के नियम के अनुसार संबंधित नियततापी जीव ठंडी जलवायु में बड़े होते हैं, क्योंकि बड़े शरीर में प्रति इकाई आयतन सतह कम होती है और इसलिए गर्मी धीरे-धीरे खोती है। एलन के नियम के अनुसार ठंडी जलवायु के जीवों के सिरे, यानी कान, अंग और थूथन, इसी कारण छोटे होते हैं; जैसे मरुस्थल की लंबे कानों वाली फ़ेनेक लोमड़ी की तुलना में छोटे कानों वाली आर्कटिक लोमड़ी।','env-bergmann-allen-rules','original_pattern_matched','NCERT Class XII, Biology -- Organisms and Populations (adaptations).','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','statement_based','hard','Consider the following statements about fruit bats (flying foxes) in India:','भारत में फल-चमगादड़ों (flying foxes) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["They are important pollinators and seed dispersers of many tropical trees.", "Under the Wildlife (Protection) Act as it stands after the 2022 amendment, they are listed in a Schedule of vermin.", "Most of them rely mainly on sight and smell, rather than echolocation, to find food."], "statements_hi": ["ये कई उष्णकटिबंधीय पेड़ों के महत्त्वपूर्ण परागणकर्ता और बीज-प्रसारक हैं।", "2022 के संशोधन के बाद के वन्यजीव (संरक्षण) अधिनियम के अनुसार, ये पीड़क जंतुओं (vermin) की एक अनुसूची में सूचीबद्ध हैं।", "इनमें से अधिकांश भोजन खोजने के लिए प्रतिध्वनि-निर्धारण के बजाय मुख्य रूप से दृष्टि और गंध पर निर्भर करते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 3 are correct. Fruit bats pollinate and spread the seeds of trees such as the silk cotton and wild banana, and, with large eyes and a keen sense of smell, most of them find fruit and flowers without the echolocation used by insect-eating bats (Rousettus, which clicks its tongue, is an exception). Statement 2 is a currency trap: until 2022, fruit bats were among the four entries of Schedule V (vermin), with the common crow, mice and rats. The 2022 amendment abolished the vermin Schedule; the Centre can still declare a species vermin for an area and period by notification under section 62.','कथन 1 और 3 सही हैं। फल-चमगादड़ सेमल और जंगली केले जैसे पेड़ों का परागण करते हैं और उनके बीज फैलाते हैं, और बड़ी आँखों तथा तेज़ गंध-शक्ति के कारण इनमें से अधिकांश कीट खाने वाले चमगादड़ों के प्रतिध्वनि-निर्धारण के बिना ही फल और फूल ढूँढ़ लेते हैं (जीभ से क्लिक करने वाला Rousettus इसका अपवाद है)। कथन 2 समय बदलने का जाल है: 2022 तक फल-चमगादड़ अनुसूची V (पीड़क जंतु) की चार प्रविष्टियों में थे, साथ में आम कौआ, चूहे और मूषक। 2022 के संशोधन ने पीड़क जंतुओं की अनुसूची समाप्त कर दी; केंद्र अब भी धारा 62 के तहत अधिसूचना द्वारा किसी प्रजाति को किसी क्षेत्र और अवधि के लिए पीड़क घोषित कर सकता है।','env-fruit-bats-vermin','original_pattern_matched','Wildlife (Protection) Act, 1972 (as amended in 2022), Schedules and section 62; Wild Life (Protection) Amendment Act, 2022; Zoological Survey of India -- bats of India.','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','mcq','medium','Which one of the following is NOT one of the ''big four'' snakes responsible for most snakebite deaths in India?','निम्नलिखित में से कौन-सा साँप भारत में साँप के काटने से होने वाली अधिकांश मौतों के लिए ज़िम्मेदार ''बड़े चार'' (big four) साँपों में नहीं है?','{}'::jsonb,'[{"id": "a", "body": "Common krait", "body_hi": "सामान्य करैत", "isCorrect": false}, {"id": "b", "body": "Russell''s viper", "body_hi": "रसेल वाइपर (दबोइया)", "isCorrect": false}, {"id": "c", "body": "King cobra", "body_hi": "किंग कोबरा (नागराज)", "isCorrect": true}, {"id": "d", "body": "Saw-scaled viper", "body_hi": "फ़ुरसा (saw-scaled viper)", "isCorrect": false}]'::jsonb,2,0.66,'The ''big four'' -- the spectacled cobra, the common krait, Russell''s viper and the saw-scaled viper -- live close to farms and villages and cause most of India''s snakebite deaths; India''s polyvalent antivenom is raised against these four. The king cobra, though highly venomous, is a shy forest snake that rarely bites people, and it is not one of them -- the tempting answer only because of its fame.','''बड़े चार'', यानी चश्मेदार नाग (spectacled cobra), सामान्य करैत, रसेल वाइपर और फ़ुरसा, खेतों और गाँवों के पास रहते हैं और भारत में साँप के काटने से होने वाली अधिकांश मौतों का कारण हैं; भारत का बहुसंयोजी (polyvalent) प्रतिविष इन्हीं चार के विरुद्ध बनाया जाता है। किंग कोबरा अत्यंत विषैला होते हुए भी वन का एक शर्मीला साँप है जो मनुष्यों को कम ही काटता है, और यह इनमें शामिल नहीं है; यह केवल अपनी प्रसिद्धि के कारण आकर्षक उत्तर लगता है।','env-big-four-snakes','original_pattern_matched','World Health Organization -- snakebite envenoming; National Centre for Disease Control -- National Action Plan for Prevention and Control of Snakebite Envenoming (2024).','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','mcq','medium','Which one of the following animals is known to use tools, such as twigs, to fish termites out of their mounds?','निम्नलिखित में से कौन-सा जीव दीमकों को उनके टीलों से निकालने के लिए टहनियों जैसे औज़ारों का उपयोग करने के लिए जाना जाता है?','{}'::jsonb,'[{"id": "a", "body": "Chimpanzee", "body_hi": "चिंपैंज़ी", "isCorrect": true}, {"id": "b", "body": "Sloth bear", "body_hi": "स्लॉथ भालू (रीछ)", "isCorrect": false}, {"id": "c", "body": "Indian pangolin", "body_hi": "भारतीय पैंगोलिन", "isCorrect": false}, {"id": "d", "body": "Common palm civet", "body_hi": "सामान्य ताड़ बिलाव", "isCorrect": false}]'::jsonb,2,0.66,'Jane Goodall''s observation of chimpanzees stripping twigs and poking them into termite mounds (1960) overturned the idea that only humans make and use tools. The sloth bear and the Indian pangolin also eat termites, but with their bodies -- the bear sucks them up through the gap in its front teeth, the pangolin licks them up with a long sticky tongue -- which is exactly why they are placed as distractors. The palm civet eats mainly fruit.','1960 में जेन गुडॉल ने देखा कि चिंपैंज़ी टहनियों को छीलकर दीमक के टीलों में डालते हैं; इससे यह धारणा टूटी कि केवल मनुष्य ही औज़ार बनाते और उनका उपयोग करते हैं। स्लॉथ भालू और भारतीय पैंगोलिन भी दीमक खाते हैं, पर अपने शरीर से: भालू सामने के दाँतों की खाली जगह से उन्हें चूसता है, और पैंगोलिन लंबी चिपचिपी जीभ से चाटता है; इसीलिए ये गलत विकल्प रखे गए हैं। ताड़ बिलाव मुख्य रूप से फल खाता है।','env-animal-tool-use','original_pattern_matched','Jane Goodall Institute -- chimpanzee tool use; NCERT Class XI, Biology -- Animal Kingdom.','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','mcq','medium','Which one of the following animals is known to change its sex during its life?','निम्नलिखित में से कौन-सा जीव अपने जीवनकाल में अपना लिंग बदलने के लिए जाना जाता है?','{}'::jsonb,'[{"id": "a", "body": "Seahorse", "body_hi": "समुद्री घोड़ा", "isCorrect": false}, {"id": "b", "body": "Sea anemone", "body_hi": "समुद्री एनीमोन", "isCorrect": false}, {"id": "c", "body": "Dolphin", "body_hi": "डॉल्फ़िन", "isCorrect": false}, {"id": "d", "body": "Clownfish", "body_hi": "क्लाउनफ़िश", "isCorrect": true}]'::jsonb,2,0.66,'Clownfish are sequential hermaphrodites: all are born male, and when the dominant female of a group dies, the largest male turns into a female. The seahorse is the trap: its male carries the fertilised eggs in a brood pouch and ''gives birth'', but it never changes sex. The sea anemone is the clownfish''s host, placed here only because the two are always pictured together.','क्लाउनफ़िश क्रमिक उभयलिंगी (sequential hermaphrodites) होती हैं: सभी नर पैदा होती हैं, और जब समूह की प्रमुख मादा मर जाती है, तो सबसे बड़ा नर मादा में बदल जाता है। समुद्री घोड़ा यहाँ जाल है: इसका नर निषेचित अंडों को शिशु-थैली में रखता है और बच्चों को ''जन्म'' देता है, पर यह कभी लिंग नहीं बदलता। समुद्री एनीमोन क्लाउनफ़िश का मेज़बान है, और यहाँ केवल इसलिए रखा गया है क्योंकि दोनों हमेशा साथ दिखाए जाते हैं।','env-clownfish-sex-change','original_pattern_matched','NCERT Class XI, Biology -- Animal Kingdom; Smithsonian Ocean -- clownfish biology.','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','mcq','easy','Which one of the following is a marsupial?','निम्नलिखित में से कौन-सा एक शिशुधानी (marsupial) प्राणी है?','{}'::jsonb,'[{"id": "a", "body": "Platypus", "body_hi": "प्लैटिपस", "isCorrect": false}, {"id": "b", "body": "Koala", "body_hi": "कोआला", "isCorrect": true}, {"id": "c", "body": "Red panda", "body_hi": "लाल पांडा", "isCorrect": false}, {"id": "d", "body": "Armadillo", "body_hi": "आर्मडिलो", "isCorrect": false}]'::jsonb,2,0.66,'Marsupials give birth to very small young that complete their development in the mother''s pouch; the koala -- often wrongly called the ''koala bear'' -- is one, like the kangaroo and wombat. The platypus is a monotreme, a mammal that lays eggs. The red panda is a placental mammal of the eastern Himalaya, related neither to the koala nor closely to the giant panda, and the armadillo is a placental mammal whose armour is often wrongly taken as a sign of a special group.','शिशुधानी प्राणी बहुत छोटे बच्चों को जन्म देते हैं, जो माँ की थैली में अपना विकास पूरा करते हैं; कोआला, जिसे प्रायः गलती से ''कोआला भालू'' कहा जाता है, कंगारू और वॉम्बैट की तरह शिशुधानी है। प्लैटिपस एक मोनोट्रीम है, यानी अंडे देने वाला स्तनधारी। लाल पांडा पूर्वी हिमालय का अपरा (placental) स्तनधारी है, जो न कोआला से संबंधित है और न विशाल पांडा का निकट संबंधी है; और आर्मडिलो भी अपरा स्तनधारी है, जिसके कवच को प्रायः गलती से किसी विशेष समूह का चिह्न मान लिया जाता है।','env-marsupials','original_pattern_matched','NCERT Class XI, Biology -- Animal Kingdom (Mammalia).','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','mcq','hard','In which one of the following birds found in India does the female mate with several males in a season, leaving each male to incubate the eggs and raise the chicks on his own?','भारत में पाए जाने वाले निम्नलिखित पक्षियों में से किसमें मादा एक ही ऋतु में कई नरों से जोड़ा बनाती है, और हर नर अकेले ही अंडे सेता है और चूज़ों को पालता है?','{}'::jsonb,'[{"id": "a", "body": "Sarus crane", "body_hi": "सारस", "isCorrect": false}, {"id": "b", "body": "White-throated kingfisher", "body_hi": "सफ़ेद गले वाला किलकिला (white-throated kingfisher)", "isCorrect": false}, {"id": "c", "body": "Pheasant-tailed jacana", "body_hi": "जलमोर (pheasant-tailed jacana)", "isCorrect": true}, {"id": "d", "body": "Indian peafowl", "body_hi": "भारतीय मोर", "isCorrect": false}]'::jsonb,2,0.66,'In the pheasant-tailed jacana of India''s lotus- and water-lily-covered wetlands, the larger female holds a territory containing several males and lays a clutch for each; the male alone incubates the eggs on a floating nest and looks after the chicks. This is polyandry with a reversal of the usual parental roles. The sarus crane pairs for life and both parents share incubation; in the white-throated kingfisher both parents dig the nest tunnel and incubate; and in the Indian peafowl, the showy male takes no part, and the female incubates alone -- the exact opposite of the jacana.','भारत की कमल और कुमुदिनी से ढकी आर्द्रभूमियों में रहने वाले जलमोर (pheasant-tailed jacana) में बड़ी मादा कई नरों वाला क्षेत्र घेरती है और हर नर के लिए अंडे देती है; नर अकेले ही तैरते घोंसले पर अंडे सेता है और चूज़ों की देखभाल करता है। यह बहुपतित्व (polyandry) है, जिसमें माता-पिता की सामान्य भूमिकाएँ उलट जाती हैं। सारस जीवन भर एक ही जोड़ा रखता है और दोनों माता-पिता मिलकर अंडे सेते हैं; सफ़ेद गले वाले किलकिले में दोनों माता-पिता घोंसले की सुरंग खोदते हैं और अंडे सेते हैं; और भारतीय मोर में दिखावटी नर कोई भाग नहीं लेता, मादा अकेले अंडे सेती है, जो जलमोर के ठीक उलट है।','env-jacana-polyandry','original_pattern_matched','Salim Ali, The Book of Indian Birds (Bombay Natural History Society); NCERT Class XII, Biology -- Organisms and Populations.','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','assertion_reason','medium','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "The number of Asiatic lions in Gujarat has risen over recent decades.", "assertion_hi": "गुजरात में एशियाई शेरों की संख्या हाल के दशकों में बढ़ी है।", "reason": "A second wild population of Asiatic lions has been established in Kuno National Park, Madhya Pradesh.", "reason_hi": "मध्य प्रदेश के कूनो राष्ट्रीय उद्यान में एशियाई शेरों की एक दूसरी जंगली आबादी बसाई जा चुकी है।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": false}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": true}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb,2,0.66,'Statement-I is correct: successive population estimations have recorded steady growth, from 284 in 1990 to 891 in 2025, with lions spreading from Gir into the wider Saurashtra landscape. Statement-II is incorrect: Kuno was chosen in the 1990s as a second home for Asiatic lions, and the Supreme Court ordered the translocation in 2013, but no lions were moved; Kuno instead received African cheetahs from 2022. The wild Asiatic lion still lives only in Gujarat, which makes a single epidemic a serious risk.','कथन-I सही है: लगातार आकलनों ने स्थिर वृद्धि दर्ज की है, 1990 के 284 से 2025 के 891 तक, और शेर गिर से निकलकर सौराष्ट्र के व्यापक भू-दृश्य में फैल गए हैं। कथन-II गलत है: 1990 के दशक में कूनो को एशियाई शेरों के दूसरे घर के रूप में चुना गया था, और उच्चतम न्यायालय ने 2013 में स्थानांतरण का आदेश दिया था, पर कोई शेर नहीं भेजा गया; इसके बजाय कूनो को 2022 से अफ़्रीकी चीते मिले। जंगली एशियाई शेर अब भी केवल गुजरात में रहता है, जिससे कोई एक महामारी गंभीर खतरा बन सकती है।','env-asiatic-lion-kuno','original_pattern_matched','Supreme Court, Centre for Environmental Law, WWF-India v. Union of India (April 2013); Gujarat Forest Department -- Asiatic lion population estimation; MoEFCC -- Project Cheetah.','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','assertion_reason','medium','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "In many bird species, the male is far more brightly coloured than the female.", "assertion_hi": "पक्षियों की कई प्रजातियों में नर मादा की तुलना में कहीं अधिक चटकीले रंग का होता है।", "reason": "Bright plumage helps the male attract females, through sexual selection.", "reason_hi": "चटकीले पंख लैंगिक चयन (sexual selection) के ज़रिए नर को मादाओं को आकर्षित करने में मदद करते हैं।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true, "reason_2": "Bright plumage camouflages the male from predators.", "reason_2_hi": "चटकीले पंख नर को शिकारियों से छिपाते (छलावरण करते) हैं।"}'::jsonb,'[{"id": "a", "body": "Both Statement II and Statement III are correct and both of them explain Statement I", "body_hi": "कथन-II और कथन-III दोनों सही हैं और ये दोनों कथन-I की व्याख्या करते हैं", "isCorrect": false}, {"id": "b", "body": "Both Statement II and Statement III are correct but only one of them explains Statement I", "body_hi": "कथन-II और कथन-III दोनों सही हैं, किंतु इनमें से केवल एक ही कथन-I की व्याख्या करता है", "isCorrect": false}, {"id": "c", "body": "Only one of the Statements II and III is correct and that explains Statement I", "body_hi": "कथन-II और कथन-III में से केवल एक सही है और वही कथन-I की व्याख्या करता है", "isCorrect": true}, {"id": "d", "body": "Neither Statement II nor Statement III is correct", "body_hi": "न तो कथन-II सही है, न ही कथन-III", "isCorrect": false}]'::jsonb,2,0.66,'Only Statement II is correct, and it explains Statement I. Where females choose mates, males with the brightest plumage or most elaborate displays leave more offspring, so the traits spread -- the peacock''s train is the textbook case. Statement III is wrong: bright colours make males more conspicuous to predators, not less; it is the duller females, who sit on the nest, that benefit from camouflage.','केवल कथन-II सही है, और यह कथन-I की व्याख्या करता है। जहाँ मादाएँ साथी चुनती हैं, वहाँ सबसे चटकीले पंखों या सबसे विस्तृत प्रदर्शन वाले नर अधिक संतानें छोड़ते हैं, इसलिए ये गुण फैलते हैं; मोर की पूँछ इसका पाठ्यपुस्तकीय उदाहरण है। कथन-III गलत है: चटकीले रंग नरों को शिकारियों के लिए अधिक दिखाई देने वाला बनाते हैं, कम नहीं; घोंसले पर बैठने वाली फीकी मादाओं को ही छलावरण का लाभ मिलता है।','env-sexual-dimorphism-birds','original_pattern_matched','NCERT Class XII, Biology -- Evolution (natural and sexual selection); Charles Darwin, The Descent of Man (1871).','draft'),
('upsc','Environment & Ecology','Fauna & Animal Behaviour','match_the_following','easy','Consider the following pairs of States and their State birds:','राज्यों और उनके राज्य पक्षियों के निम्नलिखित युग्मों पर विचार कीजिए:','{"list_1": ["1. Uttar Pradesh", "2. Bihar", "3. Maharashtra", "4. Assam"], "list_1_hi": ["1. उत्तर प्रदेश", "2. बिहार", "3. महाराष्ट्र", "4. असम"], "list_2": ["Sarus crane", "House sparrow", "Yellow-footed green pigeon", "Great hornbill"], "list_2_hi": ["सारस", "गौरैया", "हरियल (पीले पैर वाला हरा कबूतर)", "बड़ा धनेश"], "closing": "How many of the pairs given above are correctly matched?", "closing_hi": "उपर्युक्त में से कितने युग्म सही सुमेलित हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one pair", "body_hi": "केवल एक युग्म", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "body_hi": "केवल दो युग्म", "isCorrect": false}, {"id": "c", "body": "Only three pairs", "body_hi": "केवल तीन युग्म", "isCorrect": true}, {"id": "d", "body": "All four pairs", "body_hi": "सभी चार युग्म", "isCorrect": false}]'::jsonb,2,0.66,'Three pairs are correct. The sarus crane, the world''s tallest flying bird, is the State bird of Uttar Pradesh; Bihar adopted the house sparrow; and the yellow-footed green pigeon (harial) is Maharashtra''s State bird. Pair 4 is wrong: Assam''s State bird is the white-winged wood duck, an endangered forest duck; the great hornbill is the State bird of Kerala and Arunachal Pradesh.','तीन युग्म सही हैं। विश्व का सबसे ऊँचा उड़ने वाला पक्षी सारस उत्तर प्रदेश का राज्य पक्षी है; बिहार ने गौरैया को अपनाया; और हरियल (पीले पैर वाला हरा कबूतर) महाराष्ट्र का राज्य पक्षी है। युग्म 4 गलत है: असम का राज्य पक्षी सफ़ेद पंखों वाली वन-बतख (white-winged wood duck) है, जो एक संकटग्रस्त वन्य बतख है; बड़ा धनेश केरल और अरुणाचल प्रदेश का राज्य पक्षी है।','env-state-birds-pairs','original_pattern_matched','State Forest Departments -- State symbols; Zoological Survey of India -- State animals, birds, trees and flowers of India.','draft')
